// Fictional constant-debt LTV covenant. It does not encode any lender or regulator's margin rules.
export const collateralDefinitions={
 collateralTest:{title:'Keep positive equity separate from a hypothetical loan-to-collateral test',fields:[
  ['collateral','Eligible collateral value before the price stress (CAD)',100000,1000,500000,1000],
  ['loan','Debt outstanding, held constant before any adjustment (CAD)',50000,0,250000,1000],
  ['decline','Immediate decline in that collateral’s value (%)',30,0,80,5],
  ['ltvLimit','Fictional maximum loan-to-collateral ratio (%)',60,20,90,5]
 ]}
};
export function collateralAdjustment(input,decline=input.decline,ltvLimit=input.ltvLimit) {
 const value=input.collateral*(1-decline/100),cap=ltvLimit/100,debt=input.loan,equity=value-debt,ratio=debt/value;
 const paydown=Math.max(0,debt-cap*value),addition=Math.max(0,debt/cap-value);
 const internalSale=paydown===0?0:debt<value?paydown/(1-cap):null;
 return {value,debt,cap,equity,ratio,paydown,addition,internalSale,fullSaleDebtLeft:Math.max(0,debt-value),minimumValue:debt/cap,initialSlackLoss:1-debt/(cap*input.collateral)};
}
const cad=value=>'CAD '+value.toLocaleString('en-CA',{maximumFractionDigits:2});
export function collateralResult(kind,input) {
 if(kind!=='collateralTest')throw Error('Unknown collateral-test topic.');
 const p=collateralAdjustment(input),stresses=[...new Set([0,15,30,45,60,80,input.decline])].sort((a,b)=>a-b);
 const internal=p.internalSale==null?(p.fullSaleDebtLeft>0?'No partial internal sale can restore an active positive-collateral ratio in this case; a sale of all entered collateral would still leave '+cad(p.fullSaleDebtLeft)+' of debt before costs.':'No partial internal sale can restore an active positive-collateral ratio in this case; selling all entered collateral would close both positions before costs.'):'Under the same fictional terms, selling '+cad(p.internalSale)+' of existing collateral and using all proceeds immediately to repay debt would meet the test, leaving '+cad(p.value-p.internalSale)+' of collateral and '+cad(p.debt-p.internalSale)+' of debt.';
 return {metrics:[['Collateral value less debt at the selected stress',p.equity,'money'],['Outside cash to repay debt to the fictional limit',p.paydown,'money'],['Additional eligible collateral if debt stays unchanged',p.addition,'money']],note:'Original static nominal-CAD collateral illustration. This fictional contract tests debt divided by eligible collateral against the entered maximum ratio. The limit is not a CIRO, FINRA, legal or lender requirement. All entered collateral receives full eligibility value with no haircut; it falls instantly by the selected percentage. Debt stays fixed until the illustrated adjustment, with no interest, fees, tax, price slippage or intervening transactions. The selected loan-to-collateral ratio is '+(p.ratio*100).toFixed(2)+'%. External repayment reduces debt while keeping this collateral fixed. Posting additional eligible collateral leaves debt fixed. Both use resources outside the initially entered collateral pool and are alternative mathematical cases, not costs to add together or rights under an actual agreement. '+internal+' No response deadline, sale price, extension, acceptable deposit or ability to transact is promised. Actual contracts and eligibility can differ or change.',charts:[
  {id:'collateral-ratio-price-stress',type:'line',title:'The debt ratio rises as eligible collateral falls',unit:'percent',unitLabel:'Loan divided by eligible collateral value · fixed debt before adjustment',xLabel:'Immediate decline in collateral value (%)',series:[{name:'Loan-to-collateral ratio',rows:Array.from({length:17},(_,i)=>({x:i*5,value:collateralAdjustment(input,i*5).ratio}))},{name:'Fictional maximum ratio',rows:[{x:0,value:p.cap},{x:80,value:p.cap}],dash:true}],evidence:'Hypothetical collateral covenant',note:'The horizontal axis is a price stress, not a probability or time path. A ratio above the dashed line fails the fictional test even if collateral still exceeds debt. These percentages are loan-to-value ratios, not investment returns or the equity percentage required by a particular margin rule. A starting case can already exceed the selected limit; the tool does not assume that the original borrowing would have been approved.'},
  {id:'collateral-equity-bridge',type:'waterfall',title:'Positive remaining equity can coexist with a failed borrowing test',unit:'money',rows:[{label:'Collateral before stress',value:input.collateral},{label:'Immediate collateral loss',value:-input.collateral*input.decline/100},{label:'Debt outstanding',value:-input.loan}],totalLabel:'Collateral value less debt',evidence:'Hypothetical collateral snapshot',note:'This bridge measures the entered pool’s collateral value less debt before any adjustment. It is not total household net worth, and it does not deduct an outside repayment or add resources from elsewhere. The fictional ratio limit changes the required adjustment without changing this equity amount. A negative endpoint means debt exceeds the entered collateral value before transaction costs.'},
  {id:'collateral-two-external-responses',type:'groupbar',title:'Repaying debt and adding collateral require different outside amounts',unit:'money',seriesNames:['Outside cash used to repay debt','Additional fully eligible collateral'],rows:stresses.map(decline=>{const r=collateralAdjustment(input,decline);return {label:decline+'% collateral decline',values:[r.paydown,r.addition]};}),evidence:'Alternative hypothetical adjustment methods',note:'Repayment uses max(0, debt − limit × stressed collateral). Adding fully eligible collateral uses max(0, debt ÷ limit − stressed collateral). These are separate alternatives, so the two bars should not be added. An amount posted as collateral remains an owned asset in this model but becomes committed to the loan pool; repayment reduces cash and debt together. Neither amount is an investment loss or newly created wealth. Availability and lender acceptance are not assumed.'},
  {id:'collateral-cash-limit-matrix',type:'heatmap',title:'Outside debt repayment under different fictional ratio limits',unit:'money',columns:[40,50,60,70].map(v=>v+'%'),rows:[0,20,40,60].map(decline=>({label:decline+'% decline',values:[40,50,60,70].map(limit=>collateralAdjustment(input,decline,limit).paydown)})),evidence:'Hypothetical covenant sensitivity',note:'Rows replace the immediate price decline; columns replace the maximum loan-to-collateral ratio. Cells are outside cash used to reduce debt while keeping the stressed collateral unchanged. They are not additional collateral requirements, loss estimates or calls issued by a lender. A lower allowed ratio can require cash at the same asset value and debt, including before any price decline.'}
 ]};
}
